CREATE TABLE users (id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, created_at REAL NOT NULL DEFAULT (unixepoch()));
CREATE TABLE sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash BLOB UNIQUE NOT NULL, csrf_token_hash BLOB NOT NULL, expires_at REAL NOT NULL, revoked_at REAL);
CREATE TABLE conversations (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL DEFAULT '', created_at REAL NOT NULL DEFAULT (unixepoch()), updated_at REAL NOT NULL DEFAULT (unixepoch()));
CREATE INDEX conversations_owner_idx ON conversations(owner_id,updated_at DESC,id DESC);
CREATE TABLE messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, created_at REAL NOT NULL DEFAULT (unixepoch()), client_message_id TEXT, UNIQUE(conversation_id,client_message_id), UNIQUE(id,conversation_id));
CREATE INDEX messages_conversation_idx ON messages(conversation_id,seq);
CREATE TABLE runs (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_message_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','preparing_context','generating','cancelling','completed','cancelled','failed','expired','outcome_unknown')), created_at REAL NOT NULL DEFAULT (unixepoch()), updated_at REAL NOT NULL DEFAULT (unixepoch()), error_code TEXT, FOREIGN KEY(user_message_id,conversation_id) REFERENCES messages(id,conversation_id));
CREATE TABLE run_events (run_id TEXT NOT NULL REFERENCES runs(id) ON DELETE CASCADE, seq INTEGER NOT NULL CHECK(seq>0), event_id TEXT NOT NULL UNIQUE, type TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at REAL NOT NULL DEFAULT (unixepoch()), PRIMARY KEY(run_id,seq));
CREATE TABLE idempotency_keys (owner_id TEXT NOT NULL REFERENCES users(id), route TEXT NOT NULL, key TEXT NOT NULL, request_sha256 BLOB NOT NULL, response_json TEXT, expires_at REAL NOT NULL, PRIMARY KEY(owner_id,route,key));
CREATE TABLE system_mode (singleton INTEGER PRIMARY KEY CHECK(singleton=1), requested_mode TEXT NOT NULL CHECK(requested_mode IN ('normal','gaming')), controller_state TEXT NOT NULL CHECK(controller_state IN ('offline','starting','ready','stopping','stopped','error')), updated_at REAL NOT NULL DEFAULT (unixepoch()));
INSERT INTO system_mode(singleton,requested_mode,controller_state) VALUES (1,'normal','offline');
